        .heat-max { background-color: var(--h-max); border-color: #60a5fa; }

        /* Audit Panel */
        .audit-list { display: flex; flex-direction: column; gap: 8px; margin-top: 8px; }
        .audit-item { display: flex; align-items: flex-start; gap: 8px; padding: 10px; border-radius: 6px; background: rgba(255,255,255,0.02); border-left: 4px solid var(--border); font-size: 0.85rem; }
        .audit-item.danger { border-left-color: var(--danger); background: rgba(239, 68, 68, 0.05); }
        .audit-item.warning { border-left-color: var(--warning); background: rgba(245, 158, 11, 0.05); }
        .audit-item.success { border-left-color: var(--success); background: rgba(16, 185, 129, 0.05); }
        .audit-title { font-weight: 600; margin-bottom: 2px; }
        .audit-desc { color: var(--text-muted); font-size: 0.8rem; }

        /* Post Drawer List */
        .post-drawer { margin-top: 12px; max-height: 250px; overflow-y: auto; display: flex; flex-direction: column; gap: 6px; }
        .post-drawer-item { background: var(--bg-input); border: 1px solid var(--border); padding: 8px; border-radius: 6px; font-size: 0.8rem; position: relative; display: flex; flex-direction: column; justify-content: space-between; }
        .post-drawer-meta { font-size: 0.75rem; font-weight: 600; color: var(--text-muted); margin-bottom: 2px; }
        .post-drawer-title { font-weight: 500; color: var(--text-main); margin-bottom: 2px; word-break: break-word; }
        .post-drawer-cta { font-size: 0.7rem; color: var(--text-muted); }
        .delete-btn { position: absolute; top: 6px; right: 8px; color: var(--danger); cursor: pointer; font-weight: bold; font-size: 1.1rem; border: none; background: none; width: auto; margin: 0; padding: 0; }
    </style>
</head>
<body>

<div class="container">
